import{glands,glucoseState,temperatureState,glucoseRecords,freshGlucose,glucoseTimes}from './endo-models.js?v=20261023-physicscomplete01';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const et=(x,y,s,z=16,c='#f8f6f2')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-size="${z}">${esc(s)}</text>`;
const path=(d,c='#b9d1d3',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const dot=(x,y,r=6,c='#efb59c')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
export const endoSVG=(art,label)=>`<svg viewBox="0 0 560 400" role="img" aria-label="${esc(label)}"><defs><linearGradient id="endoSkin" x2="0" y2="1"><stop stop-color="#d7ab99"/><stop offset="1" stop-color="#a67773"/></linearGradient><radialGradient id="endoLiver"><stop stop-color="#daaa9d"/><stop offset="1" stop-color="#aa706e"/></radialGradient></defs>${art}</svg>`;
export function glandFigure({state='',neutral=false}={}){let a=`<circle cx="258" cy="45" r="30" fill="#536c7c" stroke="#abc2c5" stroke-width="2"/><path d="M242 76v35Q200 113 195 147l-24 115 23 5 28-91v110l-13 80h33l16-72 16 72h33l-13-80V176l28 91 23-5-24-115q-5-34-47-36V76Z" fill="#3d596d" stroke="#adc2c7" stroke-width="2"/><path d="M215 204q-16 8-9 29q9 11 19-4M299 204q16 8 9 29q-9 11-19-4" fill="#8a777c"/><path d="M215 200l10-12 10 12M287 200l10-12 10 12" fill="#e4c897"/><path d="M230 235q30-13 57-2q-26 14-57 9Z" fill="#ddc493"/><path d="M245 116q13-14 26 0q0 16-13 8q-13 8-13-8" fill="#a6c9c9"/>${dot(258,61,5,'#eeb099')}<rect x="395" y="130" width="145" height="105" rx="14" fill="#2b465d" stroke="#9eb8c0"/><path d="M424 175q30-25 60 0m-30-8v29" stroke="#c2cdd0" stroke-width="3" fill="none"/>${dot(427,184,8,'#e0b79c')+dot(481,184,8,'#e0b79c')}<rect x="395" y="255" width="145" height="100" rx="14" fill="#2b465d" stroke="#9eb8c0"/><path d="M454 276v17m-16 0q16-18 32 0" stroke="#c2cdd0" stroke-width="3" fill="none"/>${dot(445,309,8,'#e0b79c')+dot(464,309,8,'#e0b79c')} ${et(467,150,'Pelvic inset',13)+et(467,276,'Scrotal inset',13)+et(467,379,'Alternative glands',13)}`;
for(let g of glands){let on=g.id===state;a+=`<circle cx="${g.x}" cy="${g.y}" r="${on?19:13}" fill="${on?'#f2c89f':'#173047'}" stroke="#f0d4ba" stroke-width="${on?3:1}"/>`+et(g.x,g.y+5,g.letter,16,on?'#173047':'#f8f6f2');if(!neutral){let x=g.x<350?95:467,y=g.x<350?g.y: g.id==='ovaries'?220:342;a+=path(`M${g.x-15} ${g.y}L${g.x<350?153:x} ${y-6}`)+et(x,y,g.label,15);}}
return endoSVG(a+et(258,392,'Front view · schematic positions',13),'Gland positions A in head, B neck, C above kidneys, D abdomen, E pelvic inset, F scrotal inset. '+(neutral?'Identify the labelled glands.':'Named gland key shown.'));}
export function glucoseGraph({fresh=false}={}){let rec=fresh?freshGlucose:glucoseRecords,x=t=>75+t*3.35,y=v=>325-v*17,art='';for(let v of[0,5,10,15])art+=path(`M75 ${y(v)}H477`,'#5e798a',1)+et(54,y(v)+5,v,14);art+=path('M75 58V325H480');for(let t of glucoseTimes)art+=et(x(t),347,t,14);art+=et(277,377,'Time / min',16)+`<text x="21" y="195" transform="rotate(-90 21 195)" text-anchor="middle" fill="#f8f6f2" font-size="15">Blood glucose / mmol/L</text>`;
for(let [key,vals]of Object.entries(rec)){let c=key==='A'?'#efb59c':'#b8d2d4';art+=`<polyline points="${vals.map((v,i)=>x(glucoseTimes[i])+','+y(v)).join(' ')}" fill="none" stroke="${c}" stroke-width="3" ${key==='B'?'stroke-dasharray="8 5"':''}/>`;vals.forEach((v,i)=>art+=key==='A'?dot(x(glucoseTimes[i]),y(v),4,c):`<rect x="${x(glucoseTimes[i])-4}" y="${y(v)-4}" width="8" height="8" fill="${c}"/>`);}art+=path('M320 30H345','#efb59c',3)+et(364,35,'A',16)+path('M402 30H427','#b8d2d4',3)+et(446,35,'B',16);
return endoSVG(art,'Original illustrative glucose curves. Time/min: '+glucoseTimes.join(', ')+'. A/mmol/L: '+rec.A.join(', ')+'. B/mmol/L: '+rec.B.join(', ')+'. Not a diagnostic record.');}
export function temperatureFigure({state='hot',progress=0,detail=false}={}){let f=temperatureState(state),cold=state==='cold',d=f.dilated?13:5,art=et(280,31,cold?'Too cold: constrict · stop sweating · shiver':'Too hot: dilate · produce sweat',19)+`<path d="M55 140Q200 129 505 140V315H55Z" fill="url(#endoSkin)"/><path d="M55 147Q200 136 505 147" stroke="#ead4bc" stroke-width="8" fill="none"/>`+path('M100 285V215Q100 181 137 181H398Q435 181 435 215V285','#c47c7d',d)+path('M100 285V215Q100 181 137 181H398Q435 181 435 215V285','#e5b4a4',Math.max(2,d-5));
for(let i=0;i<(f.dilated?8:3);i++){let q=((progress+i/(f.dilated?8:3))%1),x=137+q*261;art+=dot(x,181,3,'#a45965');}
art+=path('M180 140V208q-33-10-28 16q45 15 17 30q-42-16-30 10q39 27 54-4q23-43-13-47','#f0d4a8',5)+et(124,116,'Sweat pore',14)+path('M160 119L180 139')+et(386,233,'Skin vessels',15)+path('M385 216V189')+et(153,299,'Sweat gland',15);
if(f.sweat)for(let i=0;i<4;i++){let q=(progress+i/4)%1;art+=`<ellipse cx="${177+Math.sin(i)*12}" cy="${130-q*60}" rx="4" ry="6" fill="#c1dce0" opacity="${1-q*.8}"/>`;}
let dx=cold?Math.sin(progress*Math.PI*16)*3:0;art+=`<g transform="translate(${dx},0)">${[0,1,2].map(i=>path(`M235 ${340+i*10}q45-14 91 0t91 0`,'#cba4a0',7)).join('')}</g>`+et(342,387,'Skeletal muscle',14);
if(detail)art+=et(280,67,cold?'Reduced surface flow; muscle respiration increases':'Surface blood flow increases; sweat evaporates',15);
return endoSVG(art,'Schematic skin section: '+(cold?'narrow skin vessels, no sweat, shivering muscle.':'dilated skin vessels and sweat production.')+' Vessels stay in place. Symbolic time and sizes.');}
export function hormoneFigure({progress=0,state='',step=4}={}){let p=Math.max(0,Math.min(1,progress)),stage=Math.min(3,Math.floor(p*4)),art=et(280,35,'A chemical signal travels in blood',21);let boxes=[[85,state==='pituitary'?'Pituitary':'Gland'],[280,'Blood'],[475,state==='pituitary'?'Other gland':'Target']];for(let[x,n]of boxes)art+=`<rect x="${x-55}" y="105" width="110" height="106" rx="24" fill="${n==='Blood'?'#496474':'#9b7778'}" stroke="#d9c8b3" stroke-width="2"/>`+et(x,245,n,18);art+=path('M145 158H220M340 158H415','#bdced0',4);let x=85+p*390;art+=`<polygon points="${x},138 ${x+9},154 ${x},170 ${x-9},154" fill="#edc48e" stroke="#fae7be"/>`+et(280,296,'◆ Hormone signal',17)+et(280,335,state==='pituitary'?'Pituitary → another endocrine gland → further hormone':'Secretion → blood transport → suitable target',16)+et(280,378,'Symbolic route and speed; not a blood-flow simulation',13);return endoSVG(art,'Hormone signal from gland through blood to target. '+state);}
export function glucoseFigure({kind='insulin',progress=0,step=5,state='',concealed=false,signal=true}={}){let active=state!=='absent',mode=kind==='glucagon'?'glucagon':'insulin',f=glucoseState({mode,progress,active}),art=et(280,29,mode==='glucagon'?'Liver glycogen → glucose in blood':'Blood glucose → uptake and storage',21)+`<rect x="35" y="85" width="205" height="210" rx="35" fill="#3b596d" stroke="#a6c4cb" stroke-width="3"/><path d="M314 97Q355 59 462 92Q508 122 487 235Q448 281 316 251Q282 176 314 97Z" fill="url(#endoLiver)" stroke="#e4bfac" stroke-width="3"/>`+et(135,326,'Blood',19)+et(399,300,mode==='glucagon'?'Liver cells':'Liver / muscle cells',17);
for(let i=0;i<f.blood;i++)art+=dot(75+(i%3)*53,126+Math.floor(i/3)*56,9,'#f4c78d');for(let i=0;i<f.store;i++){let x=335+(i%4)*35,y=145+Math.floor(i/4)*48;if(i%4)art+=path(`M${x-35} ${y}H${x}`,'#bcd0cd',4);art+=dot(x,y,9,'#f4c78d');}art+=et(400,112,'Glycogen store',15);
if(active){let x=mode==='glucagon'?310-f.fraction*75:235+f.fraction*80;art+=(f.inTransit?dot(x,200,8,'#f4c78d'):'')+path(mode==='glucagon'?'M300 235H253l10-8m-10 8 10 8':'M252 235H298l-10-8m10 8-10 8','#d3ded4',3);}
art+=(signal?`<polygon points="270,102 280,116 270,130 260,116" fill="#a6d0d2"/>`:'')+et(281,61,!signal?'Signal not released yet':mode==='glucagon'?'◆ Glucagon signal':'◆ Insulin signal',16)+et(280,360,'● Glucose units   ·   linked units = glycogen',15)+et(280,389,'Symbolic counts and timing · no dose prediction',13);return endoSVG(art,'Worked '+mode+' pathway; '+f.blood+' symbolic blood glucose units and '+f.store+' stored units, '+f.inTransit+' in transfer. Hormone is a separate signal.');}
export function feedbackFigure({state='high',progress=0}={}){let high=state==='high',text=state==='restored'?'Suitable levels restored → corrective drive decreases':high?'High glucose → insulin → uptake/storage → glucose falls':'Low glucose → glucagon → liver release → glucose rises';return endoSVG(et(280,40,'Oppose the original change',23)+`<rect x="60" y="105" width="440" height="130" rx="30" fill="#39576b" stroke="#b5cccf" stroke-width="2"/>`+et(280,148,state==='restored'?'Restored':high?'Above a suitable range':'Below a suitable range',21)+path(`M130 197H${130+progress*300}`,'#efbf9d',10)+et(280,284,text.split(' → ').slice(0,2).join(' → '),18)+et(280,318,text.split(' → ').slice(2).join(' → '),18)+et(280,375,'Feedback regulates a range; it does not demand zero fluctuation',13),'Negative feedback: '+text);}
export function endoFigure(w={}){if(w.concealed)return endoSVG(et(280,195,'Predict, then reveal the evidence',22),'Outcome concealed until prediction');if(w.kind==='glands')return glandFigure(w);if(w.kind==='temperature')return temperatureFigure(w);if(w.kind==='hormone')return hormoneFigure(w);if(w.kind==='data')return glucoseGraph(w);if(w.kind==='risk')return endoSVG(et(280,45,'Illustrative group data',22)+et(280,130,'With obesity: 20 / 100',24)+et(280,190,'Without obesity: 5 / 100',24)+et(280,262,'People recorded with Type 2 diabetes',18)+et(280,330,'Association does not guarantee an individual outcome',15),'Original fictional group counts, not a clinical study:20/100 with obesity and5/100 without have Type2 diabetes.');if(w.kind==='diabetes')return endoSVG(et(280,40,'Compare production and response',22)+et(280,132,w.state==='type2'?'Insulin produced → reduced target response':'Insufficient pancreatic insulin',20)+`<rect x="65" y="175" width="150" height="100" rx="25" fill="#a37b79"/><rect x="345" y="175" width="150" height="100" rx="25" fill="#446478"/>`+et(140,310,'Pancreas',18)+et(420,310,'Target cells',18)+path('M220 223H337','#b6d0d1',3)+et(280,375,'Mechanism comparison, not individual diagnosis',14),'Schematic Type'+(w.state==='type2'?'2: reduced target insulin response':'1: insufficient insulin production'));if(w.kind==='feedback')return feedbackFigure(w);return glucoseFigure(w);}
export const endoAssessmentFigure=f=>endoFigure({kind:f.diagram,neutral:!!f.neutral,fresh:!!f.fresh});
